mapper.select:
SELECT bl.*, u.unit_number, b.name AS building_name, c.name AS community_name, ft.name AS fee_type_name FROM bills bl JOIN units u ON bl.unit_id = u.id JOIN buildings b ON u.building_id = b.id JOIN communities c ON b.community_id = c.id JOIN fee_types ft ON bl.fee_type_id = ft.id
AND bl.status = #{status} AND bl.unit_id = #{unitId}
ORDER BY bl.id DESC
